def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 3 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            if len(cells) >= 4:
                boxes.append((min(y for y,x in cells), max(y for y,x in cells), min(x for y,x in cells), max(x for y,x in cells)))
    protected = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1 for r0,r1,c0,c1 in boxes)}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and (r, c) in protected:
                for y in range(max(0,r-1), min(h,r+2)):
                    for x in range(max(0,c-1), min(w,c+2)):
                        if (y,x) not in protected:
                            out[y][x] = 1
    return out

